'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const store = await cookies()
  const current = store.get(NOTIFICATIONS_COOKIE)?.value === 'true'
  store.set(NOTIFICATIONS_COOKIE, String(!current), {
    httpOnly: false,
    sameSite: 'lax',
    path: '/',
  })

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const store = await cookies()
  const enabled = store.get('notifications-enabled')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <button type="submit">
          Notifications: {enabled ? 'On' : 'Off'}
        </button>
      </form>
    </main>
  )
}

import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
